function rustTypes(erpSystem: string): string {
  return [
    GENERATED_HEADER_RS,
    `//! ERP surface types for ${erpSystem}.`,
    '',
    'use serde::{Deserialize, Serialize};',
    'use std::collections::HashMap;',
    '',
    '#[derive(Debug, Clone, Serialize, Deserialize)]',
    'pub struct ErpSurfaceRequest {',
    `    pub erp_type: String,`,
    '    pub operation: String,',
    '    pub entity_type: String,',
    '    #[serde(skip_serializing_if = "Option::is_none")]',
    '    pub query: Option<HashMap<String, serde_json::Value>>,',
    '    pub correlation_id: String,',
    '}',
    '',
    '#[derive(Debug, Clone, Serialize, Deserialize)]',
    'pub struct ErpSurfaceResponse {',
    '    pub id: String,',
    '    pub status: u16,',
    '    pub message: String,',
    '    pub data: serde_json::Value,',
    '    pub correlation_id: String,',
    '    pub timestamp: String,',
    '}',
    '',
  ].join('\n');
}

function rustClient(): string {
  return [
    GENERATED_HEADER_RS,
    'use crate::erp_client::types::{ErpSurfaceRequest, ErpSurfaceResponse};',
    'use crate::erp_client::retry::with_retry;',
    '',
    'const GCP_METADATA_TOKEN_URL: &str =',
    '    "http://metadata.google.internal/computeMetadata/v1/instance/service-accounts/default/identity";',
    'const REQUEST_TIMEOUT_SECS: u64 = 30;',
    '',
    'pub struct ErpSurfaceClient {',
    '    base_url: String,',
    '    service_account_email: String,',
    '    http: reqwest::Client,',
    '}',
    '',
    'impl ErpSurfaceClient {',
    '    pub fn new(base_url: String, service_account_email: String) -> Self {',
    '        let http = reqwest::Client::builder()',
    '            .timeout(std::time::Duration::from_secs(REQUEST_TIMEOUT_SECS))',
    '            .build()',
    '            .expect("Failed to build HTTP client");',
    '        let base_url = base_url.trim_end_matches(\'/\').to_string();',
    '        Self { base_url, service_account_email, http }',
    '    }',
    '',
    '    pub async fn push_entity(',
    '        &self,',
    '        request: ErpSurfaceRequest,',
    '    ) -> Result<ErpSurfaceResponse, Box<dyn std::error::Error>> {',
    '        let client = self;',
    '        with_retry(|| async {',
    '            let token = client.get_identity_token().await?;',
    '            let url = format!("{}/v1/erpsurface", client.base_url);',
    '            let response = client.http',
    '                .post(&url)',
    '                .header("Authorization", format!("Bearer {}", token))',
    '                .header("Content-Type", "application/json")',
    '                .json(&request)',
    '                .send()',
    '                .await?;',
    '',
    '            if !response.status().is_success() {',
    '                let status = response.status().as_u16();',
    '                let body = response.text().await.unwrap_or_default();',
    '                return Err(format!("ERP surface returned HTTP {}: {}", status, body).into());',
    '            }',
    '',
    '            Ok(response.json::<ErpSurfaceResponse>().await?)',
    '        }).await',
    '    }',
    '',
    '    async fn get_identity_token(&self) -> Result<String, Box<dyn std::error::Error>> {',
    '        let url = format!("{}?audience={}", GCP_METADATA_TOKEN_URL, self.service_account_email);',
    '        let token = self.http',
    '            .get(&url)',
    '            .header("Metadata-Flavor", "Google")',
    '            .send()',
    '            .await?',
    '            .error_for_status()?',
    '            .text()',
    '            .await?;',
    '        Ok(token)',
    '    }',
    '}',
    '',
  ].join('\n');
}

function rustRetry(): string {
  return [
    GENERATED_HEADER_RS,
    'use std::future::Future;',
    'use std::sync::{Arc, Mutex};',
    'use std::time::{Duration, Instant};',
    '',
    '#[derive(Debug, Clone)]',
    'pub struct RetryConfig {',
    '    pub max_attempts: u32,',
    '    pub initial_delay: Duration,',
    '    pub multiplier: u32,',
    '}',
    '',
    'impl Default for RetryConfig {',
    '    fn default() -> Self {',
    '        Self { max_attempts: 3, initial_delay: Duration::from_secs(1), multiplier: 2 }',
    '    }',
    '}',
    '',
    'pub async fn with_retry<F, Fut, T, E>(mut f: F) -> Result<T, E>',
    'where',
    '    F: FnMut() -> Fut,',
    '    Fut: Future<Output = Result<T, E>>,',
    '{',
    '    let config = RetryConfig::default();',
    '    let mut delay = config.initial_delay;',
    '    let mut last_err: Option<E> = None;',
    '',
    '    for attempt in 1..=config.max_attempts {',
    '        match f().await {',
    '            Ok(value) => return Ok(value),',
    '            Err(err) => {',
    '                last_err = Some(err);',
    '                if attempt < config.max_attempts {',
    '                    tokio::time::sleep(delay).await;',
    '                    delay *= config.multiplier;',
    '                }',
    '            }',
    '        }',
    '    }',
    '    Err(last_err.unwrap())',
    '}',
    '',
    '#[derive(Debug)]',
    'struct CircuitBreakerState {',
    '    failures: u32,',
    '    opened_at: Option<Instant>,',
    '}',
    '',
    '#[derive(Debug, Clone)]',
    'pub struct CircuitBreaker {',
    '    threshold: u32,',
    '    reset_timeout: Duration,',
    '    state: Arc<Mutex<CircuitBreakerState>>,',
    '}',
    '',
    'impl CircuitBreaker {',
    '    pub fn new(threshold: u32, reset_timeout_ms: u64) -> Self {',
    '        Self {',
    '            threshold,',
    '            reset_timeout: Duration::from_millis(reset_timeout_ms),',
    '            state: Arc::new(Mutex::new(CircuitBreakerState { failures: 0, opened_at: None })),',
    '        }',
    '    }',
    '',
    '    pub async fn execute<F, Fut, T>(&self, f: F) -> Result<T, Box<dyn std::error::Error>>',
    '    where',
    '        F: FnOnce() -> Fut,',
    '        Fut: Future<Output = Result<T, Box<dyn std::error::Error>>>,',
    '    {',
    '        {',
    '            let mut state = self.state.lock().unwrap();',
    '            if let Some(opened_at) = state.opened_at {',
    '                if opened_at.elapsed() < self.reset_timeout {',
    '                    return Err("Circuit breaker is open — downstream service unavailable".into());',
    '                }',
    '                state.failures = 0;',
    '                state.opened_at = None;',
    '            }',
    '        }',
    '        match f().await {',
    '            Ok(value) => {',
    '                self.state.lock().unwrap().failures = 0;',
    '                Ok(value)',
    '            }',
    '            Err(err) => {',
    '                let mut state = self.state.lock().unwrap();',
    '                state.failures += 1;',
    '                if state.failures >= self.threshold {',
    '                    state.opened_at = Some(Instant::now());',
    '                }',
    '                Err(err)',
    '            }',
    '        }',
    '    }',
    '}',
    '',
    'impl Default for CircuitBreaker {',
    '    fn default() -> Self { Self::new(5, 60_000) }',
    '}',
    '',
  ].join('\n');
}

// ============================================================================
// File Writing
// ============================================================================

function writeClientFile(absPath: string, content: string): void {
  const dir = absPath.substring(0, absPath.lastIndexOf('/'));
  mkdirSync(dir, { recursive: true, mode: DIR_MODE });
  try {
    writeFileSync(absPath, content, { encoding: 'utf-8', mode: FILE_MODE });
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    throw new Error(`ECLI-P4-061: Failed to write ERP client file ${absPath}: ${message}`);
  }
}

// ============================================================================
// Public: Pipeline Entry Point
// ============================================================================

export function generateErpClient(context: Phase4Context): Phase4StageOutput {
  const startTime = Date.now();
  const rootSpan = createSpan('erp-client-generation', 'generate-erp-client', {
    phase4Dir: context.phase4Dir,
    traceId: context.traceId,
  });

  try {
    const erpStage = context.stageOutputs.get('erp-target-resolution');
    if (!erpStage || erpStage.status !== 'completed') {
      throw new Error(
        'ECLI-P4-060: ERP target resolution not available on context. ' +
        'Ensure the erp-target-resolution stage completed successfully before running erp-client-generation.',
      );
    }
    const erpResolution = erpStage.data as ERPResolution;
    const erpSystem = erpResolution.erpSystem;

    const language = context.phase3Artifacts.implementationLanguage;

    // Non-TS/Rust languages handled by Ruflo swarm
    if (!hasTemplateSupport(language)) {
      const span = endSpan(rootSpan, 'ok', { delegated: true, language });
      emitSpan(span);
      return {
        stage: 'erp-client-generation',
        status: 'completed',
        data: { files: [], endpointCount: 0 } satisfies ERPClientOutput,
        artifacts: [],
        timing: Date.now() - startTime,
        summary: `ERP client for ${language} delegated to Ruflo swarm.`,
      };
    }

    const isTs = language === 'typescript';

    const clientDir = join(context.phase4Dir, 'project', 'src', 'erp-client');
    mkdirSync(clientDir, { recursive: true, mode: DIR_MODE });

    const clientFiles: ClientFile[] = [];
    const writtenPaths: string[] = [];

    const genSpan = createSpan(
      'erp-client-generation',
      'generate-files',
      { language, erpSystem },
      rootSpan.spanId,
    );

    // ADR-029 Fix 1: Load tech stack from Phase 2 for ERP-specific API paths
    const techStack = loadTechStack(context.phase2Dir);
    const erpPaths = techStack?.erp
      ? getERPOperationPaths(techStack.erp.slug)
      : getERPOperationPaths(erpResolution.erpSystem.toLowerCase().includes('sap') ? 'sap-s4hana'
        : erpResolution.erpSystem.toLowerCase().includes('oracle') ? 'oracle-fusion'
        : erpResolution.erpSystem.toLowerCase().includes('workday') ? 'workday'
        : erpResolution.erpSystem.toLowerCase().includes('dynamics') ? 'dynamics-365'
        : erpResolution.erpSystem.toLowerCase().includes('infor') ? 'infor-cloudsuite'
        : 'netsuite');

    if (isTs) {
      const files: Array<{ name: string; content: string }> = [
        { name: 'types.ts', content: tsTypes(erpSystem) },
        { name: 'mapper.ts', content: tsMapper(erpSystem) },
        { name: 'client.ts', content: tsClient(erpSystem, erpPaths) },
        { name: 'retry.ts', content: tsRetry() },
      ];

      for (const file of files) {
        const absPath = join(clientDir, file.name);
        writeClientFile(absPath, file.content);
        const relPath = `project/src/erp-client/${file.name}`;
        clientFiles.push({ relativePath: relPath, content: file.content, kind: 'erp-client' });
        writtenPaths.push(absPath);
      }
    } else {
      const rustClientDir = join(context.phase4Dir, 'project', 'src', 'erp_client');
      mkdirSync(rustClientDir, { recursive: true, mode: DIR_MODE });

      const files: Array<{ name: string; content: string }> = [
        { name: 'types.rs', content: rustTypes(erpSystem) },
        { name: 'client.rs', content: rustClient() },
        { name: 'retry.rs', content: rustRetry() },
      ];

      for (const file of files) {
        const absPath = join(rustClientDir, file.name);
        writeClientFile(absPath, file.content);
        const relPath = `project/src/erp_client/${file.name}`;
        clientFiles.push({ relativePath: relPath, content: file.content, kind: 'erp-client' });
        writtenPaths.push(absPath);
      }

      const modContent = [GENERATED_HEADER_RS, 'pub mod client;', 'pub mod retry;', 'pub mod types;', ''].join('\n');
      const modPath = join(rustClientDir, 'mod.rs');
      writeClientFile(modPath, modContent);
      clientFiles.push({ relativePath: 'project/src/erp_client/mod.rs', content: modContent, kind: 'erp-client' });
      writtenPaths.push(modPath);
    }

    // 4 domain operations: createTransferOrder, createPurchaseOrder, getInventoryBalance, updateItemReceipt
    const endpointCount = 4;

    const finalGenSpan = endSpan(genSpan, 'ok', { filesGenerated: writtenPaths.length, endpointCount });
    emitSpan(finalGenSpan);

    const finalRootSpan = endSpan(rootSpan, 'ok', {
      language, erpSystem, filesGenerated: writtenPaths.length, endpointCount,
    });
    emitSpan(finalRootSpan);

    const timing = Date.now() - startTime;
    const output: Phase4StageOutput = {
      stage: 'erp-client-generation',
      status: 'completed',
      data: { files: clientFiles, endpointCount } satisfies ERPClientOutput,
      artifacts: writtenPaths,
      timing,
      summary: `Generated ERP client (${language}) for ${erpSystem}: ${writtenPaths.length} files, ${endpointCount} endpoint types (${timing}ms)`,
    };

    context.stageOutputs.set('erp-client-generation', output);
    return output;
  } catch (err: unknown) {
    const errorMessage = err instanceof Error ? err.message : String(err);
    const finalRootSpan = endSpan(rootSpan, 'error', { error: errorMessage });
    emitSpan(finalRootSpan);

    const timing = Date.now() - startTime;
    const output: Phase4StageOutput = {
      stage: 'erp-client-generation',
      status: 'failed',
      data: { error: errorMessage },
      artifacts: [],
      timing,
      summary: `ERP client generation failed: ${errorMessage}`,
    };

    context.stageOutputs.set('erp-client-generation', output);
    return output;
  }
}
